// === Normalização do lead recebido do site (via /api/subscribe) ===
const raw = $input.first().json;
const input = raw.body || raw;

const email = String(input.email || '').trim().toLowerCase();

// Guarda de segurança: sem e-mail válido não há nada para salvar
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('E-mail inválido ou ausente no payload recebido: "' + email + '"');
}

const agora = new Date();

// Data/hora legível no fuso de São Paulo (ex.: 18/08/2026 14:32:07)
const dataFormatada = new Intl.DateTimeFormat('pt-BR', {
  dateStyle: 'short',
  timeStyle: 'medium',
  timeZone: 'America/Sao_Paulo'
}).format(agora);

// Primeiro nome sugerido a partir do e-mail (maria.silva@... -> Maria)
const bruto = email.split('@')[0].split(/[._+-]/)[0].replace(/[0-9]/g, '');
const nome = bruto ? bruto.charAt(0).toUpperCase() + bruto.slice(1) : 'Inscrito';

return [{
  json: {
    email: email,
    nome: nome,
    origem: String(input.origem || 'Landing Page Em Desenvolvimento'),
    marca: String(input.marca || 'Gabriela Lopes'),
    data_registro: dataFormatada,
    criado_em: String(input.dataRegistro || agora.toISOString()),
    user_agent: String(input.userAgent || 'Desconhecido').slice(0, 300),
    ip: String(input.ip || 'Desconhecido').slice(0, 100)
  }
}];
